'use strict';
(async()=>{
  const C=window.GRECore,base=window.GRE_PLATFORM_DATA,legacy=window.GREReadingBridge;
  const mock=window.GREMockExam,V=window.GREVocabulary,AI=window.GREVocabularyAI,QA=window.GREQuestionAI;
  if(!C||!base)return;
  const $=s=>document.querySelector(s),E=C.escape,KEY='gre-training-progress-v2';
  const statusNames={verified:'来源已核验',extracted:'已提取 · 未完整核验',needs_review:'存在疑点',incomplete:'内容不完整'};
  let bank=base,questions=new Map(),sources=new Map(),materials=new Map(),view='home',page=1,importKind='progress',warning='',storageOK=true,toastTimer,db;
  const defaults=()=>({version:2,attempts:[],favorites:[],vocabulary:[],questionAnalysis:{},notes:{},notesUpdatedAt:{},essays:[],drafts:{},sessions:[],session:null,migratedBookmarks:[],updatedAt:0});
  let state=defaults(),initializing=true,restoring=false,savedContent='';
  const config={subject:'all',types:[],sources:[],group:'',difficulty:'',length:'',count:20,mode:'free',minutes:20,status:'',instant:true,wrongFirst:false,gradedOnly:false};
  let reviewFilter={subject:'',type:'',search:''},sessionClock=Date.now(),essayClock=Date.now(),writingId=null,writingLimit=30,writingEnd=null,writingExpired=false;
  function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4200);}
  function indexBank(){questions=new Map(bank.questions.map(q=>[q.question_id,q]));sources=new Map(bank.sources.map(s=>[s.id,s]));materials=new Map(bank.materials.map(m=>[m.id,m]));}
  function idbOpen(){return new Promise(resolve=>{try{const req=indexedDB.open('gre-training-local-v2',1);req.onupgradeneeded=()=>req.result.createObjectStore('data');req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null);}catch{resolve(null);}});}
  function dbGet(key){return new Promise(resolve=>{if(!db)return resolve(null);const req=db.transaction('data').objectStore('data').get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null);});}
  function dbSet(key,value){return new Promise((resolve,reject)=>{if(!db)return reject(Error('浏览器未提供 IndexedDB'));const tx=db.transaction('data','readwrite');tx.objectStore('data').put(value,key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});}
  function validState(input){
    if(!input||input.version!==2||!Array.isArray(input.attempts)||!Array.isArray(input.favorites))throw Error('不是阅间综合训练的进度文件。');
    const out=defaults(),seen=new Set();
    out.attempts=input.attempts.filter(a=>a&&typeof a.id==='string'&&!seen.has(a.id)&&seen.add(a.id)&&questions.has(a.questionId)&&Number.isFinite(a.at)&&(a.correct===null||typeof a.correct==='boolean')).map(a=>({...a,elapsedMs:Number.isFinite(a.elapsedMs)&&a.elapsedMs>=0?a.elapsedMs:null,selected:Array.isArray(a.selected)?a.selected.filter(v=>typeof v==='string'):[],text:typeof a.text==='string'?a.text:'',uncertain:a.uncertain===true}));
    for(const a of out.attempts)if(!questions.get(a.questionId).gradable){if(a.correct!==null)a.originalCorrect=a.correct;a.correct=null;}
    out.favorites=[...new Set(input.favorites.filter(id=>questions.has(id)))];
    out.vocabulary=V.normalizeEntries(input.vocabulary);
    out.questionAnalysis=QA?.normalizeCache(input.questionAnalysis,questions,materials)||{};
    for(const [id,n]of Object.entries(input.notes||{}))if(questions.has(id)&&typeof n==='string')out.notes[id]=n;
    for(const [id,at]of Object.entries(input.notesUpdatedAt||{}))if(questions.has(id)&&Number.isFinite(at))out.notesUpdatedAt[id]=at;
    out.essays=Array.isArray(input.essays)?input.essays.filter(e=>e&&typeof e.id==='string'&&questions.get(e.questionId)?.category==='AWA'&&typeof e.text==='string'&&Number.isFinite(e.at)):[];
    for(const [id,d]of Object.entries(input.drafts||{}))if(questions.has(id)&&d&&typeof d.text==='string')out.drafts[id]={text:d.text,updatedAt:Number(d.updatedAt)||0,elapsedMs:Math.max(0,Number(d.elapsedMs)||0)};
    out.sessions=Array.isArray(input.sessions)?input.sessions.filter(s=>s&&typeof s.id==='string'&&Number.isFinite(s.endedAt)&&Array.isArray(s.ids)):[];
    out.sessions=out.sessions.map(s=>{
      const ids=s.ids.filter(id=>questions.has(id)),responses={};
      if(s.kind==='mock'&&(!Array.isArray(s.mockVisitedIds)||typeof s.mockExamId!=='string'))throw Error('模考历史的题目清单或考试ID格式错误，原记录已保留。');
      for(const [id,r]of Object.entries(s.responses||{}))if(ids.includes(id)&&r)responses[id]={selected:Array.isArray(r.selected)?r.selected.filter(v=>typeof v==='string'):[],text:typeof r.text==='string'?r.text:'',submitted:r.submitted===true,correct:questions.get(id).gradable&&typeof r.correct==='boolean'?r.correct:null,uncertain:r.uncertain===true,elapsedMs:Number.isFinite(r.elapsedMs)?Math.max(0,r.elapsedMs):0};
      return {...s,ids,responses,mockVisitedIds:s.kind==='mock'?[...new Set(s.mockVisitedIds.filter(id=>ids.includes(id)&&questions.get(id)?.category!=='AWA'))]:undefined,startedAt:Number.isFinite(s.startedAt)?s.startedAt:s.endedAt,omittedQuestionIds:s.ids.filter(id=>!questions.has(id))};
    }).filter(s=>s.ids.length);
    out.migratedBookmarks=Array.isArray(input.migratedBookmarks)?input.migratedBookmarks.filter(v=>typeof v==='string'):[];
    const s=input.session;
    if(s&&Array.isArray(s.ids)&&s.ids.length&&s.ids.every(id=>questions.has(id))&&Number.isFinite(s.startedAt)){
      const ids=s.ids.slice(0,500),index=Number.isFinite(s.index)?Math.max(0,Math.min(Math.trunc(s.index),ids.length-1)):0;
      out.session={id:typeof s.id==='string'?s.id:uid(),ids,index,startedAt:s.startedAt,mode:['free','timed','exam'].includes(s.mode)?s.mode:'free',minutes:Number.isFinite(s.minutes)?Math.max(1,Math.min(360,s.minutes)):20,instant:s.mode==='exam'?false:s.instant!==false,endedAt:Number.isFinite(s.endedAt)?s.endedAt:null,responses:{}};
      for(const [qid,r]of Object.entries(s.responses||{}))if(ids.includes(qid)&&r)out.session.responses[qid]={selected:Array.isArray(r.selected)?r.selected.filter(v=>typeof v==='string'):[],text:typeof r.text==='string'?r.text:'',uncertain:r.uncertain===true,elapsedMs:Number.isFinite(r.elapsedMs)?Math.max(0,r.elapsedMs):0,submitted:r.submitted===true,correct:questions.get(qid).gradable&&typeof r.correct==='boolean'?r.correct:null};
    }
    out.updatedAt=Number.isFinite(input.updatedAt)?input.updatedAt:0;return out;
  }
  const uid=()=>Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,9);
  let saveQueue=Promise.resolve(true);
  function save({preserveTimestamp=initializing||restoring,silent=false,force=false}={}){const content=JSON.stringify({...state,updatedAt:0}),changed=content!==savedContent;if(!changed&&!force)return saveQueue;if(changed&&!preserveTimestamp)state.updatedAt=Date.now();savedContent=content;const snapshot=JSON.parse(JSON.stringify(state));if(changed&&!silent&&!preserveTimestamp)window.GREPortable?.changed();let quickSaved=false;if(storageOK)try{localStorage.setItem(KEY,JSON.stringify(snapshot));quickSaved=true;}catch{storageOK=false;warning='浏览器快速存储空间不足，正在使用本地数据库保存。建议导出备份。';}
    if(db)saveQueue=saveQueue.then(()=>dbSet('progress',snapshot)).then(()=>true).catch(()=>{if(!quickSaved){warning='当前浏览器无法保存，请导出记录备份。';toast(warning);}return quickSaved;});else{saveQueue=Promise.resolve(quickSaved);if(!quickSaved)toast('当前记录未能持久保存，请导出备份。');}updateSide();return saveQueue;}
  function importLegacy(){
    if(restoring)return;
    if(!legacy)return;const rc=legacy.readProgress(),known=new Set(state.attempts.map(a=>a.id));let changed=false;
    for(const h of rc.history||[]){const id=`rc:${h.qid}:${h.at}`;if(questions.has(h.qid)&&!known.has(id)){state.attempts.push({id,questionId:h.qid,at:h.at,correct:h.correct,uncertain:h.uncertain===true,elapsedMs:null,selected:[],text:'',origin:'legacy-rc'});known.add(id);changed=true;}}
    for(const pid of rc.bookmarks||[])if(!state.migratedBookmarks.includes(pid)){for(const q of bank.questions.filter(q=>q.legacy_passage_id===pid))if(!state.favorites.includes(q.question_id))state.favorites.push(q.question_id);state.migratedBookmarks.push(pid);changed=true;}
    if(changed)save();
  }
  indexBank();db=await idbOpen();
  const imported=await dbGet('imported-banks');if(Array.isArray(imported))for(const b of imported)try{mergeBank(C.validateBank(b));}catch(e){warning='部分旧导入题库格式异常，已保留原存储。';}
  let stored;try{stored=JSON.parse(localStorage.getItem(KEY)||'null');}catch{storageOK=false;warning='旧综合进度格式异常，已保留原值；可导出当前记录。';}
  const durable=await dbGet('progress');if(durable&&(!stored||durable.updatedAt>stored.updatedAt))stored=durable;
  if(stored)try{state=validState(stored);}catch(e){storageOK=false;warning=e.message+' 原存储未覆盖。';}
  savedContent=JSON.stringify({...state,updatedAt:0});importLegacy();window.addEventListener('gre-rc-progress',importLegacy);
  function updateSide(){if(view==='rc')return;const done=new Set(state.attempts.map(a=>a.questionId)).size;$('#side-count').textContent=`${done} / ${bank.questions.length}`;$('#side-bar').style.width=`${Math.min(100,done/bank.questions.length*100)}%`;}
  function syncVisibility(){const isRC=view==='rc';$('#main').hidden=!isRC;$('#platform-main').hidden=isRC;$('#legacy-nav').hidden=!isRC;$('#platform-content').hidden=view==='mock';$('#mock-content').hidden=view!=='mock';if(view!=='mock')mock?.leave();document.querySelectorAll('[data-pview]').forEach(b=>{b.classList.toggle('active',b.dataset.pview===view);b.setAttribute('aria-current',b.dataset.pview===view?'page':'false');});}
  function go(next){accrue();view=next;page=1;if(['verbal','quant','writing','mixed','home'].includes(next)){config.subject={verbal:'Verbal',quant:'Quant',writing:'AWA',mixed:'all',home:config.subject}[next];config.types=[];config.sources=[];config.group='';}
    syncVisibility();if(next==='rc'){legacy.navigate('library');return;}render();window.scrollTo({top:0});}
  function header(title,description,kicker='YOUR GRE TRAINING DESK'){return `<header class="platform-header"><div><p class="eyebrow">${E(kicker)}</p><h1>${E(title)}</h1><p class="description">${E(description)}</p></div><div class="row">${state.session&&!state.session.endedAt?'<button class="button secondary small" data-paction="resume">继续上次练习 ↗</button>':''}<span class="pill">GRE · LOCAL</span></div></header>${warning?`<div class="platform-warning">${E(warning)}</div>`:''}`;}
  function tag(q){return `<span class="tag">${E(C.types[q.question_type])}</span><span class="tag status-${q.answer_status}">${E(statusNames[q.answer_status]||q.answer_status)}</span>`;}
  const sourceName=q=>sources.get(q.source_id)?.title||q.source_file||q.source_id;
  let vocabularySearch='',vocabularyPage=1,vocabularySaved=true;
  const vocabularySaveStatus=()=>vocabularySaved===null?'正在保存…':vocabularySaved?'自动保存在当前浏览器':'尚未保存到本机，请导出备份';
  function savedVocabularyWord(word,questionId){return state.vocabulary.some(entry=>entry.word===V.normalize(word)&&entry.sources.some(source=>source.questionId===questionId));}
  function vocabularyPanel(q,r){
    const material=materials.get(q.material_id);
    if(!r?.submitted||!V.eligible(q,material))return '';
    const groups=V.groups(q,material),count=state.vocabulary.filter(entry=>entry.sources.some(source=>source.questionId===q.question_id)).length;
    const chips=group=>`<div class="vocabulary-chips">${group.words.map(({word,context})=>{const saved=savedVocabularyWord(word,q.question_id);return `<button type="button" class="vocabulary-chip" data-vocab-word="${E(word)}" data-vocab-context="${E(context)}" aria-pressed="${saved}" ${saved?'disabled':''} lang="en">${saved?'✓ ':''}${E(word)}</button>`;}).join('')}</div>`;
    return `<section class="vocabulary-panel" data-vocab-question="${E(q.question_id)}" aria-label="收藏本题生词"><div class="row space-between"><h3>留下这题的生词</h3><button class="text-link" data-pview="vocabulary">打开生词本 ↗</button></div><p class="vocabulary-hint">点词即保存，也可以补充词组。不需要收藏时，直接继续下一题。</p>${groups.filter(group=>group.words.length).map((group,i)=>i===0?`<p class="vocabulary-label">${E(group.label)}</p>${chips(group)}`:`<details class="vocabulary-group"><summary>${E(group.label)}中的词（${group.words.length}）</summary>${chips(group)}</details>`).join('')}<form class="vocabulary-form"><label class="field">补充单词或词组<input name="word" type="text" maxlength="80" placeholder="例如 take for granted" autocomplete="off" required></label><button class="button secondary small" type="submit">保存生词</button></form><p class="vocabulary-count tiny" role="status">本题已选 ${count} 个生词 · ${vocabularySaveStatus()}</p></section>`;
  }
  function syncVocabularyPanels(){
    document.querySelectorAll('.vocabulary-panel').forEach(panel=>{
      const id=panel.dataset.vocabQuestion;
      panel.querySelectorAll('[data-vocab-word]').forEach(button=>{const saved=savedVocabularyWord(button.dataset.vocabWord,id);button.disabled=saved;button.setAttribute('aria-pressed',String(saved));button.textContent=(saved?'✓ ':'')+button.dataset.vocabWord;});
      panel.querySelector('.vocabulary-count').textContent=`本题已选 ${state.vocabulary.filter(entry=>entry.sources.some(source=>source.questionId===id)).length} 个生词 · ${vocabularySaveStatus()}`;
    });
  }
  async function saveVocabularyWord(panel,raw,clickedContext){
    const q=questions.get(panel?.dataset.vocabQuestion),r=q&&state.session?.responses[q.question_id];
    if(!q||!r?.submitted||!V.eligible(q,materials.get(q.material_id)))return;
    if(!V.validWord(raw)){toast('请输入英文单词或词组，最多 80 个字符。');return;}
    const word=V.normalize(raw);
    if(savedVocabularyWord(word,q.question_id)){toast('这个词已保存在本题的生词中。');return;}
    const candidate=V.groups(q,materials.get(q.material_id)).flatMap(group=>group.words).find(item=>item.word===word);
    const context=clickedContext||candidate?.context||q.question_content;
    const at=Date.now(),source={questionId:q.question_id,questionType:q.question_type,source:sourceName(q),section:q.source_section||'',context:context===q.question_content?context:`${context}\n\n题干：${q.question_content}`,addedAt:at};
    state.vocabulary=V.add(state.vocabulary,word,source,at);vocabularySaved=null;syncVocabularyPanels();vocabularySaved=await save();syncVocabularyPanels();toast(vocabularySaved?`已保存「${word}」到生词本。`:'生词尚未保存到本机，请立即导出学习进度备份。');
    if(vocabularySaved)AI?.enqueue(state.vocabulary.find(entry=>entry.word===word));
  }
  function renderVocabularyResults(){
    const search=vocabularySearch.trim().toLowerCase(),list=state.vocabulary.filter(entry=>!search||[entry.word,...entry.sources.map(source=>`${source.source} ${source.section} ${source.context}`)].join(' ').toLowerCase().includes(search)).sort((a,b)=>b.addedAt-a.addedAt),pages=Math.max(1,Math.ceil(list.length/30));
    vocabularyPage=Math.max(1,Math.min(vocabularyPage,pages));
    $('#vocabulary-results').innerHTML=list.length?`<p class="muted vocabulary-total">${list.length} 个生词${search?'符合搜索条件':''}</p><div class="vocabulary-list">${list.slice((vocabularyPage-1)*30,vocabularyPage*30).map(entry=>`<article class="panel vocabulary-entry"><div class="row space-between"><h2 lang="en">${E(entry.word)}</h2><button class="text-link" data-vocab-remove="${E(entry.word)}" aria-label="移除生词 ${E(entry.word)}">移除</button></div><p class="tiny">${new Date(entry.addedAt).toLocaleDateString('zh-CN')} 收藏 · ${entry.sources.length} 道来源题目</p>${AI?.entryHTML(entry)||''}${entry.sources.map(source=>`<details class="vocabulary-source"><summary>${E(C.types[source.questionType]||source.questionType||'来源题目')} · ${E(source.source||source.questionId)}${source.section?' · '+E(source.section):''}</summary><p lang="en">${E(source.context)}</p><p class="tiny">题目编号：${E(source.questionId)}</p></details>`).join('')}</article>`).join('')}</div>${pages>1?`<div class="pager"><button class="button secondary small" data-vocab-page="${vocabularyPage-1}" ${vocabularyPage===1?'disabled':''}>← 上一页</button><span>${vocabularyPage} / ${pages}</span><button class="button secondary small" data-vocab-page="${vocabularyPage+1}" ${vocabularyPage===pages?'disabled':''}>下一页 →</button></div>`:''}`:`<div class="platform-empty"><h2>${search?'没有找到这个词。':'把做题遇到的生词，留在这里。'}</h2><p>${search?'试试其他单词或来源名称。':'完成填空、六选二或短／中篇阅读后，点击题目下方的单词即可收藏。'}</p></div>`;
    AI?.refresh();
  }
  function renderVocabulary(){
    $('#platform-content').innerHTML=header('把陌生的词，慢慢变成熟悉。','保留你选择的生词和原题语境，可随全部学习进度导出、导入。','YOUR VOCABULARY')+`${AI?.settingsHTML()||''}<label class="field small-search">搜索生词或来源<input id="vocabulary-search" type="search" value="${E(vocabularySearch)}" placeholder="输入单词、词组或资料名称"></label><div id="vocabulary-results"></div><div class="platform-bank-actions"><button class="button secondary" data-paction="export-progress">导出全部学习进度（含生词）↓</button><button class="button secondary" data-paction="import-progress">导入学习进度 ↑</button></div>`;
    renderVocabularyResults();
  }
  function sourceURL(id,pages=[]){const s=sources.get(id);if(!s)return '';const url=s.url||s.reader?.url;if(!C.localAsset(url))return '';const page=pages?.[0]||1;return `${url}${url.endsWith('.pdf')?'#page='+(s.reader?.pageMap?.[page]||page):''}`;}
  function sourceLink(id,pages=[],label){const url=sourceURL(id,pages);return url?`<a class="text-link" href="${E(url)}" target="_blank" rel="noopener">${E(label||sources.get(id)?.title||id)}${pages.length?' · 原第 '+E(pages.join('、'))+' 页':''} ↗</a>`:'';}
  function images(items){return (items||[]).filter(i=>C.localAsset(i.src)).map(i=>`<figure><a href="${E(i.src)}" target="_blank" rel="noopener"><img class="question-image" src="${E(i.src)}" alt="${E(i.caption||'原资料题目图像')}" loading="lazy"></a>${i.caption?`<figcaption class="image-caption">${E(i.caption)} · 点击查看原尺寸</figcaption>`:''}</figure>`).join('');}
  const lastAttempt=id=>{for(let i=state.attempts.length-1;i>=0;i--)if(state.attempts[i].questionId===id)return state.attempts[i];return null;};
  function filterQuestions(){const latest=new Map(state.attempts.map(a=>[a.questionId,a])),everWrong=new Set(state.attempts.filter(a=>a.correct===false||a.uncertain).map(a=>a.questionId));return bank.questions.filter(q=>{
    if(q.answer_status==='incomplete')return false;
    if(config.subject==='VQ'&&q.category==='AWA'||!['all','VQ'].includes(config.subject)&&q.category!==config.subject)return false;
    if(config.types.length&&!config.types.includes(q.question_type))return false;
    const ids=[q.source_id,...(q.source_refs||[]).map(r=>r.source_id||r.sourceId)];
    if(config.sources.length&&!ids.some(id=>config.sources.includes(id)))return false;
    if(config.group&&!ids.some(id=>sources.get(id)?.group===config.group))return false;
    if(config.difficulty&&q.difficulty!==config.difficulty)return false;
    if(config.length&&materials.get(q.material_id)?.length!==config.length)return false;
    if(config.gradedOnly&&!q.gradable)return false;
    if(config.status==='new'&&latest.has(q.question_id)||config.status==='wrong'&&!everWrong.has(q.question_id)||config.status==='saved'&&!state.favorites.includes(q.question_id))return false;
    return true;
  });}
  function options(items,value,label){return `${label!==undefined?`<option value="">${E(label)}</option>`:''}`+items.map(item=>{const [id,text]=Array.isArray(item)?item:[item,item];return `<option value="${E(id)}" ${Array.isArray(value)?value.includes(id)?'selected':'':value===id?'selected':''}>${E(text)}</option>`;}).join('');}
  function configHTML(){const available=[...new Set(bank.questions.filter(q=>config.subject==='all'||config.subject==='VQ'&&q.category!=='AWA'||q.category===config.subject).map(q=>q.question_type))];return `<section class="panel training-panel"><div class="row space-between"><h2>今天，想怎么练？</h2><span class="tiny">${bank.questions.length.toLocaleString()} 道本地题目</span></div><div class="config-grid"><label class="field">科目<select data-config="subject">${options([['all','全部题型'],['Verbal','Verbal · 语文'],['Quant','Quant · 数学'],['AWA','AWA · 写作'],['VQ','Verbal + Quant']],config.subject)}</select></label><label class="field">资料组<select data-config="group">${options([...new Set(bank.sources.map(s=>s.group).filter(Boolean))],config.group,'全部资料组')}</select></label><label class="field">原资料难度<select data-config="difficulty">${options([['easy','简单'],['medium','中等'],['hard','困难'],['unknown','未标难度']],config.difficulty,'全部难度')}</select></label><label class="field">学习状态<select data-config="status">${options([['new','未做过'],['wrong','答错过 / 不确定'],['saved','已收藏']],config.status,'全部')}</select></label><label class="field">训练方式<select data-config="mode">${options([['free','自由练习'],['timed','限时练习'],['exam','模拟练习 · 结束后解析']],config.mode)}</select></label><label class="field">题目数量<input id="p-count" data-config="count" type="number" min="1" max="500" value="${config.count}"><span class="count-presets">${[10,20,30,50].map(n=>`<button data-pcount="${n}" class="${config.count===n?'active':''}">${n}</button>`).join('')}<span class="tiny">或输入</span></span></label><label class="field">限时（分钟）<input data-config="minutes" type="number" min="1" max="360" value="${config.minutes}" ${config.mode==='free'?'disabled':''}></label><label class="field">RC 篇幅<select data-config="length">${options(['短篇','中篇','长篇'],config.length,'不限篇幅')}</select></label><label class="field config-full">指定来源（可按 Ctrl / ⌘ 多选；不选表示全部）<select data-config="sources" multiple size="3">${options(bank.sources.filter(s=>s.imported_count).map(s=>[s.id,s.title]),config.sources)}</select></label><div class="config-full"><span class="field">具体题型 · 不勾选表示全部</span><div class="type-choices">${available.map(t=>`<label class="type-choice"><input type="checkbox" data-ptype="${E(t)}" ${config.types.includes(t)?'checked':''}>${E(C.types[t]||t)}</label>`).join('')}</div></div></div><div class="config-checks"><label><input type="checkbox" data-config="instant" ${config.instant&&config.mode!=='exam'?'checked':''} ${config.mode==='exam'?'disabled':''}>即时显示答案与解析</label><label><input type="checkbox" data-config="wrongFirst" ${config.wrongFirst?'checked':''}>错题优先</label><label><input type="checkbox" data-config="gradedOnly" ${config.gradedOnly?'checked':''}>仅含可核验答案的客观题</label></div><div class="config-footer"><div><p id="filter-count" class="muted">当前符合条件：${filterQuestions().length.toLocaleString()} 题</p><p class="tiny">模拟练习按自选题库组卷，不代表现行官方考试结构。</p></div><button class="button" data-paction="start">开始本次训练 →</button></div></section>`;}
  function card(q){const a=lastAttempt(q.question_id),saved=state.favorites.includes(q.question_id);return `<article class="platform-question-card"><div class="row space-between"><div class="row">${tag(q)}</div><button class="bookmark ${saved?'saved':''}" data-pfavorite="${E(q.question_id)}" aria-label="${saved?'取消收藏':'收藏题目'}" aria-pressed="${saved}">${saved?'★':'☆'}</button></div><p class="excerpt" lang="en">${E(q.question_content||'原题包含公式或图表，点击查看完整原题。')}</p><p class="source-name">${E(sourceName(q))} · ${E(q.source_section||'')} ${q.source_page?.length?'· 第 '+q.source_page[0]+' 页':''}</p><footer><span class="tiny">${a?a.correct===true?'最近答对':a.correct===false?'最近答错':'已练习':'未练习'}${q.images?.length?' · 含原题图像':''}</span><button class="text-link" data-popen="${E(q.question_id)}">${q.category==='AWA'?'开始写作':'练习此题'} →</button></footer></article>`;}
  function pageList(list){const pages=Math.max(1,Math.ceil(list.length/10));page=Math.min(page,pages);return list.length?`<div class="platform-list">${list.slice((page-1)*10,page*10).map(card).join('')}</div><div class="pager"><button class="button secondary small" data-ppage="${page-1}" ${page===1?'disabled':''}>← 上一页</button><span>${page} / ${pages} · ${list.length} 题</span><button class="button secondary small" data-ppage="${page+1}" ${page===pages?'disabled':''}>下一页 →</button></div>`:'<div class="platform-empty"><h2>暂时没有符合条件的题目。</h2><p>放宽来源、题型或学习状态条件后再试。</p></div>';}
  function renderHome(){const titles={home:['把每一种题型，都练扎实。','从本地资料出发，自由组合科目、题型和练习节奏。'],verbal:['读懂逻辑，也选准词义。','RC 保留完整文章与原练习器；TC 多空同题作答，SE 严格六选二。'],quant:['让每一个推导，都有依据。','原题公式和图表保留原样；不同数学题型使用各自的输入方式。'],mixed:['按自己的目标，组合一场训练。','可混合语文、数学与写作；共用文章和图表始终与题目关联。'],writing:['给思考一段完整的时间。','使用原始 Issue 与 Argument 材料，计时写作、自动保存、回看与导出。']};const [title,desc]=titles[view]||titles.home;
    $('#platform-content').innerHTML=header(title,desc)+(view==='home'?`<div class="platform-intro"><section class="platform-welcome"><p class="eyebrow">ONE LIBRARY. YOUR OWN PACE.</p><h2>一桌资料，一次专注。</h2><p>原题、原答案、原出处。把分散的资料变成可以持续练习的题库，留住每一次作答的过程。</p></section><div class="subject-doors">${[['verbal','V','Verbal','RC / TC / SE'],['quant','Q','Quant','数量 · 代数 · 图表'],['writing','A','AWA','题目 · 作文 · 复盘']].map(([v,l,t,d])=>`<button class="subject-door" data-pview="${v}"><span class="letter">${l}</span><strong>${t}</strong><small>${d}</small></button>`).join('')}</div></div>`:'')+configHTML()+(view==='writing'?`<div class="row space-between"><h2 class="section-heading">写作题库</h2><button class="button secondary small" data-paction="essay-history">历史作文（${state.essays.length}）</button></div>`:'<h2 class="section-heading">符合条件的题目</h2>')+`<div id="p-results">${pageList(filterQuestions())}</div>`;
  }
  const shuffled=items=>{const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
  function startPractice(ids){accrue();if(!ids.length){toast('没有符合条件的题目。');return;}state.session={id:uid(),ids,index:0,startedAt:Date.now(),mode:config.mode,minutes:config.minutes,instant:config.mode==='exam'?false:config.instant,endedAt:null,responses:{}};sessionClock=Date.now();save();view='practice';syncVisibility();render();window.scrollTo({top:0});}
  function startSubjectPractice({subject,count=20}={}){
    const draw=window.GREMockCore.createSubjectPractice(bank,{subject,count});
    if(!draw.ids.length)throw Error('这门科目暂时没有答案已核验的题目。');
    Object.assign(config,{subject,types:[],sources:[],group:'',difficulty:'',length:'',count,mode:'free',minutes:20,status:'',instant:true,wrongFirst:false,gradedOnly:true});
    startPractice(draw.ids);
    if(draw.ids.length<count)toast(`当前有 ${draw.ids.length} 道合格题目，已全部加入本组。`);
    return draw;
  }
  function getPracticeSession(){const s=state.session;if(!s||s.endedAt)return null;const cats=new Set(s.ids.map(id=>questions.get(id)?.category));if(cats.size!==1)return null;const subject=[...cats][0];return ['Verbal','Quant'].includes(subject)?{id:s.id,subject,count:s.ids.length,answered:Object.values(s.responses).filter(r=>r.submitted).length}:null;}
  function resumeSubjectPractice(){if(!getPracticeSession())return;accrue();view='practice';sessionClock=Date.now();render();window.scrollTo({top:0});}
  function startFiltered(){if(!Number.isInteger(config.count)||config.count<1||config.count>500){toast('题量请输入 1–500 的整数。');return;}if(!Number.isFinite(config.minutes)||config.minutes<1||config.minutes>360){toast('限时请输入 1–360 分钟。');return;}let list=shuffled(filterQuestions());if(config.wrongFirst)list.sort((a,b)=>Number(!!(lastAttempt(b.question_id)?.correct===false||lastAttempt(b.question_id)?.uncertain))-Number(!!(lastAttempt(a.question_id)?.correct===false||lastAttempt(a.question_id)?.uncertain)));list=list.slice(0,config.count);const ordered=[],groups=new Set();for(const q of list){const group=q.material_id||q.question_id;if(groups.has(group))continue;groups.add(group);ordered.push(...list.filter(x=>(x.material_id||x.question_id)===group).sort((a,b)=>(a.question_order||0)-(b.question_order||0)));}if(list.length<config.count)toast(`当前只有 ${list.length} 题，已按实际数量组卷。`);startPractice(ordered.map(q=>q.question_id));}
  function current(){const s=state.session,q=questions.get(s.ids[s.index]);return {s,q,r:s.responses[q.question_id] ||= {selected:[],text:'',uncertain:false,elapsedMs:0,submitted:false,correct:null}};}
  function accrue(){if(view==='practice'&&state.session&&!state.session.endedAt){const {r}=current();if(!r.submitted)r.elapsedMs+=Math.max(0,Date.now()-sessionClock);sessionClock=Date.now();}if(view==='essay'&&writingId){const d=state.drafts[writingId];if(d)d.elapsedMs=(d.elapsedMs||0)+Math.max(0,Date.now()-essayClock);essayClock=Date.now();}}
  function submitCurrent(){const {s,q,r}=current();if(r.submitted)return;if(!C.complete(q,r)){toast(C.mode(q)==='pair'?'请选择恰好两个答案。':'请完成本题作答。');return;}accrue();r.correct=C.grade(q,r);r.submitted=true;const at=Date.now();state.attempts.push({id:q.legacy_rc_id?`rc:${q.question_id}:${at}`:uid(),questionId:q.question_id,at,correct:r.correct,elapsedMs:r.elapsedMs,selected:[...r.selected],text:r.text,uncertain:r.uncertain,sessionId:s.id});if(q.category==='AWA')storeEssay(q,r.text,r.elapsedMs);if(q.legacy_rc_id)legacy.recordExternal(q.question_id,r,r.correct,at);save();renderPractice();}
  function materialHTML(q){const m=materials.get(q.material_id);if(!m)return '';const h=q.highlights||m.highlights||[];let text=(m.paragraphs?.length?m.paragraphs:[m.text||'']).map(t=>`<p>${highlight(t,h)}</p>`).join('');return `<article class="panel platform-material"><p class="eyebrow">${q.category==='Verbal'?'READ THE PASSAGE':'SHARED MATERIAL'}</p><h2>${E(m.title||'共用材料')}</h2>${images(m.images)}<div class="passage-text" lang="en">${text}</div><div class="original-links">${sourceLink(q.source_id,q.source_page)}</div>${m.translation?`<details class="annotation"><summary>原书译文</summary><p>${E(m.translation)}</p></details>`:''}${q.legacy_passage_id?`<button class="text-link legacy-return" data-legacy-passage="${E(q.legacy_passage_id)}">在原阅读练习器中打开整篇 ↗</button>`:''}</article>`;}
  function highlight(text,marks){const ranges=[];for(const mark of marks){const h=typeof mark==='string'?mark:mark?.text;if(!h)continue;let start=text.indexOf(h);while(start!==-1){ranges.push([start,start+h.length]);start=text.indexOf(h,start+h.length);}}ranges.sort((a,b)=>a[0]-b[0]);let result='',at=0;for(const [start,end]of ranges){if(start<at)continue;result+=E(text.slice(at,start))+`<mark>${E(text.slice(start,end))}</mark>`;at=end;}return result+E(text.slice(at));}
  function optionHTML(o,q,r,show){const selected=r.selected.includes(o.id),right=show&&q.gradable&&q.correct_answer.includes(o.id),wrong=show&&q.gradable&&selected&&!right;return `<button class="option ${selected?'selected':''} ${right?'correct':''} ${wrong?'incorrect':''}" data-poption="${E(o.id)}" aria-pressed="${selected}" ${r.submitted?'disabled':''}><span class="option-key">${E(o.label||o.id)}</span><span class="option-text" lang="en">${E(o.text)}</span></button>`;}
  function interaction(q,r,show){const m=C.mode(q);if(m==='writing')return `<label class="field">本题作文<textarea class="essay-editor" id="p-response-text" spellcheck="false" ${r.submitted?'disabled':''}>${E(r.text)}</textarea></label><p class="tiny">写作仅保存练习，不自动评分。</p>`;if(m==='numeric')return `<label class="numeric-entry"><input id="p-response-text" type="text" inputmode="decimal" value="${E(r.text)}" placeholder="例如 0.5 或 1/2" aria-label="数值答案" ${r.submitted?'disabled':''}><small>${E(q.numeric_format?.unit||'数字或分数')}${q.numeric_format?.precision?'<br>精度要求：'+E(q.numeric_format.precision):''}</small></label>`;if(m==='open')return `<label class="field">记录你的答案<textarea id="p-response-text" rows="4" ${r.submitted?'disabled':''}>${E(r.text)}</textarea></label><p class="tiny">按原资料自行核对，不做选择题式自动评分。</p>`;if(q.blank_groups?.length>1)return `<div class="blanks-layout" style="--blanks:${q.blank_groups.length}">${q.blank_groups.map((g,i)=>`<section class="blank-group"><h3>Blank ${i+1}</h3><div class="options">${g.options.map(o=>optionHTML(o,q,r,show)).join('')}</div></section>`).join('')}</div>`;return `<div class="options">${(q.options?.length?q.options:q.blank_groups?.[0]?.options||[]).map(o=>optionHTML(o,q,r,show)).join('')}</div>`;}
  function renderPractice(){if(!state.session){go('home');return;}if(state.session.endedAt){renderSummary();return;}const {s,q,r}=current(),show=r.submitted&&s.instant,m=C.mode(q);$('#platform-content').innerHTML=header('专注于眼前这一题。',`${C.types[q.question_type]} · ${sourceName(q)}`,'FOCUS & PRACTICE')+`<div class="study-toolbar"><div class="row"><button class="text-link" data-pview="home">← 返回首页</button><span class="tiny">第 ${s.index+1} / ${s.ids.length} 题</span>${tag(q)}</div><div class="row"><span class="timer" id="p-timer"></span><button class="button secondary small" data-pfavorite="${E(q.question_id)}">${state.favorites.includes(q.question_id)?'★ 已收藏':'☆ 收藏'}</button><button class="button ghost small" data-paction="finish">结束本次</button></div></div><div class="practice-frame ${q.material_id?'':'solo'}">${materialHTML(q)}<div><section class="panel question-panel"><p class="eyebrow">QUESTION ${s.index+1}</p>${q.answer_status!=='verified'?`<p class="reader-notes">${E(statusNames[q.answer_status])} · 此题不计正式正确率，请核对原页。</p>`:''}<p class="question-stem" lang="en">${E(q.question_content)}</p>${images(q.images)}${q.quantities?`<div class="quantity-pair"><div><h3>Quantity A</h3><p>${E(q.quantities.a)}</p></div><div><h3>Quantity B</h3><p>${E(q.quantities.b)}</p></div></div>`:''}${q.instructions?`<p class="writing-instructions">${E(q.instructions)}</p>`:''}<p class="question-kind">${{pair:'六选二 · 两个答案都正确才得分',blanks:'每空选择一个答案 · 所有空都正确才得分',multiple:'多选 · 选择全部正确选项',single:'单选 · 选择一个答案',numeric:'按原题要求输入数值或分数',writing:'写作练习 · 自动保存内容',open:'原资料自答练习'}[m]}</p>${interaction(q,r,show)}${vocabularyPanel(q,r)}${r.submitted?(show?answerHTML(q,r):'<div class="platform-answer"><h3>作答已记录。</h3><p>本次设置为结束后显示答案与解析。</p></div>'):`<div class="submit-row"><label class="confidence"><input id="p-uncertain" type="checkbox" ${r.uncertain?'checked':''}>我还不太确定</label><button class="button" data-paction="submit" ${C.complete(q,r)?'':'disabled'}>提交本题 →</button></div>`}<div class="original-links">${sourceLink(q.source_id,q.source_page)}</div>${q.notes?.length?`<details class="annotation"><summary>原题与数据核验说明</summary>${q.notes.map(n=>`<p>${E(n)}</p>`).join('')}</details>`:''}<details class="annotation"><summary>我的笔记</summary><textarea class="platform-note" id="p-note" placeholder="写下这题的依据或容易出错的地方…">${E(state.notes[q.question_id]||'')}</textarea></details></section><div class="platform-session-nav"><button class="button secondary" data-pnext="${s.index-1}" ${s.index===0?'disabled':''}>← 上一题</button><span class="tiny">${Object.values(s.responses).filter(r=>r.submitted).length} / ${s.ids.length} 已提交</span>${s.index<s.ids.length-1?`<button class="button" data-pnext="${s.index+1}">下一题 →</button>`:'<button class="button" data-paction="finish">完成本次 ✓</button>'}</div><div class="platform-qnav">${s.ids.map((id,i)=>`<button data-pnext="${i}" class="${s.index===i?'active':''} ${s.responses[id]?.submitted?'done':''}" aria-label="第${i+1}题">${i+1}</button>`).join('')}</div></div></div>`;tick();}
  function answerHTML(q,r){return originalAnswerHTML(q,r)+(QA?.panelHTML(q,materials.get(q.material_id))||'');}
  function originalAnswerHTML(q,r){const text=r.correct===true?(r.uncertain?'答对了，记得再巩固一次。':'答案正确。'):r.correct===false?'再核对一下原题的依据。':q.category==='AWA'?'作文已保存，不自动评分。':'本题不计正式正确率。';return `<section class="platform-answer ${r.correct===false?'wrong':r.correct===null?'ungraded':''}"><h3>${text}</h3>${q.correct_answer?.length?`<p>原资料答案：<strong>${E(q.correct_answer.join('、'))}</strong></p>`:(q.answer_text||q.raw_answer)?`<p>原资料答案：${E(q.answer_text||q.raw_answer)}</p>`:'<p>原资料未提供可以确认的标准答案。</p>'}${q.explanation_images?.length?images(q.explanation_images):q.explanation?`<div class="explanation-text">${E(q.explanation)}</div>`:'<p>此题未附可可靠提取的逐题解析。</p>'}${q.explanation_images?.length&&q.explanation?`<details><summary>原提取解析文字（公式以原图为准）</summary><p>${E(q.explanation)}</p></details>`:''}${q.guidance?`<details><summary>原资料指导</summary><p>${E(q.guidance)}</p></details>`:''}${q.model_essay?`<details><summary>原资料范文</summary><p>${E(q.model_essay)}</p></details>`:''}<div class="original-links">${q.answer_source?sourceLink(q.answer_source.source_id,q.answer_source.pages||[],'原答案出处'):''}${q.explanation_source?sourceLink(q.explanation_source.source_id,q.explanation_source.pages||[],'原解析出处'):''}</div>${q.source_refs?.length>1?`<details><summary>多个资料版本（${q.source_refs.length}）</summary>${q.source_refs.map(ref=>`<p>${E(sources.get(ref.source_id||ref.sourceId)?.title||ref.source_file||ref.source_id||ref.sourceId)} · 原答案 ${E((ref.correct_answer||ref.answer||[]).join('、')||ref.answerText||'未附')}</p>`).join('')}</details>`:''}</section>`;}
  function finishSession(auto=false){if(!state.session||state.session.endedAt)return;accrue();const s=state.session;for(const id of s.ids){const q=questions.get(id),r=s.responses[id];if(r&&!r.submitted&&C.complete(q,r)){const at=Date.now();r.correct=C.grade(q,r);r.submitted=true;state.attempts.push({id:q.legacy_rc_id?`rc:${id}:${at}`:uid(),questionId:id,at,correct:r.correct,elapsedMs:r.elapsedMs,selected:r.selected,text:r.text,uncertain:r.uncertain,sessionId:s.id});if(q.legacy_rc_id)legacy.recordExternal(id,r,r.correct,at);if(q.category==='AWA')storeEssay(q,r.text,r.elapsedMs);}}s.endedAt=Date.now();state.sessions.push(JSON.parse(JSON.stringify(s)));save();renderSummary();window.scrollTo({top:0});if(auto)toast('计时结束，已保存已填写答案并展示结果。');}
  function renderSummary(){const s=state.session,rs=Object.values(s.responses).filter(r=>r.submitted),graded=rs.filter(r=>r.correct!==null),correct=graded.filter(r=>r.correct).length;$('#platform-content').innerHTML=header('这一轮，给自己一个清楚的反馈。','每次作答都保留历史；未核验题与写作不混入正确率。','SESSION REVIEW')+`<section class="panel session-summary"><h2 class="session-result-title">本次练习完成</h2><p class="muted">${s.ids.length} 题 · 用时 ${formatTime(Math.round((s.endedAt-s.startedAt)/1000))}</p><div class="stats">${stat('已作答',rs.length,`共 ${s.ids.length} 题`)}${stat('正确率',graded.length?Math.round(correct/graded.length*100)+'%':'—',`${correct} / ${graded.length} 道核验题`)}${stat('不计判分',rs.length-graded.length,'写作或未核验题')}${stat('未作答',s.ids.length-rs.length,'保留为未完成')}</div><div class="row" style="justify-content:center"><button class="button" data-pview="errors">复习错题 →</button><button class="button secondary" data-pview="home">返回训练首页</button></div></section><h2 class="section-heading">逐题复盘</h2><div class="stack">${s.ids.map((id,i)=>{const q=questions.get(id),r=s.responses[id];return `<details class="panel"><summary>第 ${i+1} 题 · ${E(C.types[q.question_type])} · ${r?.submitted?r.correct===true?'正确':r.correct===false?'错误':'已记录':'未作答'}</summary><p class="question-stem">${E(q.question_content)}</p>${q.material_id?`<p class="writing-prompt">${E(materials.get(q.material_id)?.text||'')}</p>${images(materials.get(q.material_id)?.images)}`:''}${images(q.images)}<p>你的答案：${E(r?.text||r?.selected?.join('、')||'未作答')}</p>${vocabularyPanel(q,r)}${answerHTML(q,r||{correct:null})}<button class="button secondary small" data-popen="${E(id)}">再练此题</button></details>`;}).join('')}</div>`;}
  function stat(label,value,note){return `<div class="stat"><label>${E(label)}</label><strong>${E(value)}</strong><small>${E(note)}</small></div>`;}
  function tick(){if(view==='practice'&&state.session&&!state.session.endedAt){const s=state.session,elapsed=Math.max(0,Math.floor((Date.now()-s.startedAt)/1000)),remaining=s.minutes*60-elapsed;const el=$('#p-timer');if(el)el.textContent=s.mode==='free'?'用时 '+formatTime(elapsed):'剩余 '+formatTime(Math.max(0,remaining));if(s.mode!=='free'&&remaining<=0)finishSession(true);}if(view==='essay'&&writingEnd){const remaining=Math.max(0,Math.ceil((writingEnd-Date.now())/1000));if($('#essay-timer'))$('#essay-timer').textContent='剩余 '+formatTime(remaining);if(!remaining&&!writingExpired){writingExpired=true;accrue();save();toast('写作计时结束，草稿已保存；你可以继续修改。');}}}
  const formatTime=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(Math.floor(n%60)).padStart(2,'0')}`;
  // Additional views and event handlers are defined below.
  function combinedBank(current,extra){const known=new Map(current.questions.map(q=>[q.question_id,q]));for(const q of extra.questions){if(known.has(q.question_id)){if(JSON.stringify(known.get(q.question_id).question_content)!==JSON.stringify(q.question_content))throw Error('相同题目ID对应不同内容，请为新版使用不同ID。');continue;}known.set(q.question_id,q);}return {...current,questions:[...known.values()],sources:[...new Map([...extra.sources,...current.sources].map(s=>[s.id,s])).values()],materials:[...new Map([...extra.materials,...current.materials].map(m=>[m.id,m])).values()]};}
  function mergeBank(extra){const before=bank.questions.length;bank=combinedBank(bank,extra);indexBank();return bank.questions.length-before;}
  function render(){syncVisibility();if(view==='mock')mock?.render();else if(view==='practice')renderPractice();else if(view==='essay')renderEssay();else if(view==='essay-history')renderEssayHistory();else if(view==='errors'||view==='favorites')renderReview();else if(view==='vocabulary')renderVocabulary();else if(view==='analytics')renderAnalytics();else if(view==='materials')renderMaterials();else if(view!=='rc')renderHome();updateSide();}
  function openEssay(id){accrue();writingId=id;state.drafts[id] ||= {text:'',updatedAt:Date.now(),elapsedMs:0};essayClock=Date.now();writingEnd=null;writingExpired=false;view='essay';render();window.scrollTo({top:0});}
  function storeEssay(q,text,elapsedMs){const essay={id:uid(),questionId:q.question_id,text,at:Date.now(),elapsedMs:elapsedMs||0,wordCount:text.trim()?text.trim().split(/\s+/).length:0};state.essays.push(essay);return essay;}
  function writingReferences(q){return `${q.guidance_status==='needs_review'||q.guidance_source?.status==='needs_review'||q.guidance_source?.answer_status==='needs_review'?'<div class="reader-notes">配套指导的文字提取有疑点，请以原PDF为准。</div>':''}${q.guidance?`<details class="annotation"><summary>原资料写作指导 / 提纲</summary><p>${E(q.guidance)}</p>${q.guidance_source?sourceLink(q.guidance_source.source_id,q.guidance_source.pages||[]):''}</details>`:''}${q.model_essay?`<details class="annotation"><summary>查看原资料范文</summary><p class="writing-prompt">${E(q.model_essay)}</p></details>`:''}${q.supplements?.length?`<details class="annotation"><summary>配套资料与核验说明</summary>${q.supplements.map(s=>`<p>${E(s.title||s.note||s.notes||s.kind||'原资料补充')} ${s.status==='needs_review'||s.answer_status==='needs_review'?'（文字提取待核验）':''}</p>${s.source_id?sourceLink(s.source_id,s.pages||[]):''}`).join('')}</details>`:''}`;}
  function renderEssay(){const q=questions.get(writingId);if(!q){go('writing');return;}const d=state.drafts[writingId];$('#platform-content').innerHTML=header('写下来，让思路完整地展开。',`${C.types[q.question_type]} · ${sourceName(q)}`,'ANALYTICAL WRITING')+`<div class="study-toolbar"><button class="text-link" data-pview="writing">← 返回写作题库</button><div class="row"><label class="field"><select id="essay-limit" aria-label="写作限时">${options([['15','15 分钟'],['30','30 分钟'],['45','45 分钟'],['60','60 分钟']],String(writingLimit))}</select></label><button class="button secondary small" data-paction="writing-timer">${writingEnd?'重新计时':'开始计时'}</button><span id="essay-timer" class="timer">未开始计时</span><button class="button ghost small" data-paction="random-essay">随机换题 ↻</button></div></div><div class="writing-layout"><article class="panel"><div class="row space-between">${tag(q)}<button class="bookmark ${state.favorites.includes(q.question_id)?'saved':''}" data-pfavorite="${E(q.question_id)}" aria-label="收藏写作题目">${state.favorites.includes(q.question_id)?'★':'☆'}</button></div><p class="writing-prompt" style="margin-top:20px">${E(q.question_content)}</p>${q.instructions?`<p class="writing-instructions">${E(q.instructions)}</p>`:'<p class="reader-notes">此资料未提供独立写作指令；本练习保留原题文本。</p>'}${images(q.images)}<div class="original-links">${sourceLink(q.source_id,q.source_page)}</div>${writingReferences(q)}${q.notes?.length?`<details class="annotation"><summary>题目说明</summary>${q.notes.map(n=>`<p>${E(n)}</p>`).join('')}</details>`:''}</article><section><textarea class="essay-editor" id="essay-text" aria-label="作文正文" placeholder="Start writing here…" spellcheck="false">${E(d.text)}</textarea><div class="essay-meta"><span id="essay-words">${d.text.trim()?d.text.trim().split(/\s+/).length:0} words</span><span id="essay-saved">草稿保存在当前浏览器</span></div><div class="essay-actions"><button class="button" data-paction="save-essay">保存为历史作文 ✓</button><button class="button secondary" data-paction="export-essay">导出作文 ↓</button><button class="button ghost" data-paction="essay-history">查看历史作文</button></div><p class="source-note">草稿随输入自动保存。范文与指导来自资料原文，不进行自动评分。</p></section></div>`;tick();}
  function renderEssayHistory(){const drafts=Object.entries(state.drafts).filter(([id,d])=>questions.get(id)?.category==='AWA'&&d.text.trim());$('#platform-content').innerHTML=header('留下每一版，看到思路的变化。','每次保存形成独立历史版本；继续写作不会覆盖此前作文。','WRITING ARCHIVE')+`<button class="button secondary small" data-pview="writing">← 返回写作题库</button><h2 class="section-heading">未完成草稿</h2>${drafts.length?drafts.map(([id,d])=>`<article class="essay-history-item"><strong>${E(C.types[questions.get(id).question_type])} · ${E(questions.get(id).question_content.slice(0,100))}</strong><p>${E(d.text.slice(0,260))}</p><button class="text-link" data-popen="${E(id)}">继续写作 →</button></article>`).join(''):'<p class="muted">暂无草稿。</p>'}<h2 class="section-heading">历史作文（${state.essays.length}）</h2>${state.essays.length?[...state.essays].reverse().map(e=>`<article class="essay-history-item"><div class="row space-between"><strong>${E(C.types[questions.get(e.questionId)?.question_type]||'写作')} · ${new Date(e.at).toLocaleString('zh-CN')}</strong><span class="tiny">${e.wordCount||0} words · ${formatTime(Math.round((e.elapsedMs||0)/1000))}</span></div><p>${E(e.text)}</p><div class="row"><button class="text-link" data-export-essay="${E(e.id)}">导出这一版 ↓</button><button class="text-link" data-view-essay="${E(e.id)}">阅读全文</button></div></article>`).join(''):'<div class="platform-empty">保存作文后，这里会保留每个版本。</div>'}`;}
  function renderReview(){const latest=new Map(state.attempts.map(a=>[a.questionId,a]));let list=bank.questions.filter(q=>view==='favorites'?state.favorites.includes(q.question_id):latest.has(q.question_id)&&(latest.get(q.question_id).correct===false||latest.get(q.question_id).uncertain));list=list.filter(q=>(!reviewFilter.subject||q.category===reviewFilter.subject)&&(!reviewFilter.type||q.question_type===reviewFilter.type)&&(!reviewFilter.search||(q.question_content+' '+sourceName(q)).toLowerCase().includes(reviewFilter.search.toLowerCase())));$('#platform-content').innerHTML=header(view==='favorites'?'把值得再练的题，放在这里。':'回到错题，找到思路的断点。',view==='favorites'?'按科目和题型筛选收藏，原阅读文章收藏仍保留在原练习器中。':'最近答错或不确定的题目进入此处；所有历史作答仍完整保留。','REVIEW & REMEMBER')+`<div class="review-filters"><label class="field">科目<select data-review-filter="subject">${options(['Verbal','Quant','AWA'],reviewFilter.subject,'全部科目')}</select></label><label class="field">题型<select data-review-filter="type">${options(Object.entries(C.types),reviewFilter.type,'全部题型')}</select></label><label class="field">搜索题目或来源<input data-review-filter="search" type="search" value="${E(reviewFilter.search)}"></label></div><div id="review-results">${pageList(list)}</div>`;}
  function renderAnalytics(){const st=C.stats(state.attempts,bank),latest=new Map(state.attempts.map(a=>[a.questionId,a])),wrong=[...latest.values()].filter(a=>a.correct===false||a.uncertain).length;const days=Array.from({length:14},(_,i)=>{const d=new Date();d.setDate(d.getDate()-13+i);const date=d.toLocaleDateString('en-CA'),as=state.attempts.filter(a=>new Date(a.at).toLocaleDateString('en-CA')===date),g=as.filter(a=>a.correct!==null);return {label:`${d.getMonth()+1}/${d.getDate()}`,n:as.length,rate:g.length?Math.round(g.filter(a=>a.correct).length/g.length*100):null};}),max=Math.max(1,...days.map(d=>d.n));$('#platform-content').innerHTML=header('用记录，看清自己的节奏。','保留重复练习历史。旧阅读记录没有计时数据，因此不计入平均答题时间。','LEARNING ANALYTICS')+`<div class="stats">${stat('累计作答',st.total,`涉及 ${latest.size} 道不同题目`)}${stat('正式正确率',st.graded?Math.round(st.correct/st.graded*100)+'%':'—',`${st.correct} / ${st.graded} 次核验作答`)}${stat('平均答题时间',st.timed?formatTime(Math.round(st.time/st.timed/1000)):'—',`${st.timed} 次有计时记录`)}${stat('待复习 / 收藏',wrong+' / '+state.favorites.length,'错题与不确定 / 已收藏')}</div><div class="stats">${['Verbal','Quant','AWA'].map(cat=>stat(cat,st.byCategory[cat]||0,'累计作答次数')).join('')}${stat('历史作文',state.essays.length,'每次保存独立留存')}</div><div class="two-columns"><section class="panel"><h2>各题型正确率</h2><div class="table-scroll"><table class="platform-table"><thead><tr><th>题型</th><th>作答</th><th>已判分</th><th>正确率</th></tr></thead><tbody>${Object.entries(st.byType).map(([t,r])=>`<tr><td>${E(C.types[t])}</td><td>${r.total}</td><td>${r.graded}</td><td>${r.graded?Math.round(r.correct/r.graded*100)+'%':'—'}</td></tr>`).join('')||'<tr><td colspan="4">完成练习后显示统计。</td></tr>'}</tbody></table></div></section><section class="panel"><h2>最近十四天</h2><p class="muted">每日作答量 · 悬停查看正确率</p><div class="graph-days">${days.map(d=>`<div class="graph-day" title="${d.label}：${d.n} 次，正确率 ${d.rate===null?'无判分':d.rate+'%'}"><span>${d.n}</span><i style="height:${Math.max(2,d.n/max*100)}px"></i><span>${d.label}</span><small>${d.rate===null?'—':d.rate+'%'}</small></div>`).join('')}</div></section></div><h2 class="section-heading">最近练习成绩</h2><div class="panel table-scroll"><table class="platform-table"><thead><tr><th>日期</th><th>题量</th><th>已作答</th><th>正确率</th><th>用时</th><th></th></tr></thead><tbody>${[...state.sessions].reverse().slice(0,20).map(s=>{const r=Object.values(s.responses||{}).filter(r=>r.submitted),g=r.filter(r=>r.correct!==null),scoreTotal=s.kind==='mock'?(s.mockVisitedIds||[]).filter(id=>questions.get(id)?.gradable).length:g.length;return `<tr><td>${new Date(s.endedAt).toLocaleString('zh-CN')}</td><td>${s.ids.length}</td><td>${r.length}</td><td>${scoreTotal?Math.round(g.filter(r=>r.correct).length/scoreTotal*100)+'%':'—'}${s.kind==='mock'?' · 模考':''}</td><td>${formatTime(Math.round((s.endedAt-s.startedAt)/1000))}</td><td><button class="text-link" data-session-result="${E(s.id)}">复盘</button></td></tr>`;}).join('')||'<tr><td colspan="6">暂无已结束的综合练习。</td></tr>'}</tbody></table></div><h2 class="section-heading">资料完成情况</h2><div class="source-browser">${bank.sources.filter(s=>s.imported_count).map(s=>{const qs=bank.questions.filter(q=>q.source_id===s.id||q.source_refs?.some(r=>(r.source_id||r.sourceId)===s.id)),done=qs.filter(q=>latest.has(q.question_id)).length;return `<article class="panel"><h3>${E(s.title)}</h3><div class="progress-mini"><span style="width:${qs.length?done/qs.length*100:0}%"></span></div><p>${done} / ${qs.length} 道题已练习</p></article>`;}).join('')}</div><div class="platform-bank-actions"><button class="button" data-paction="export-progress">导出全部学习进度 ↓</button><button class="button secondary" data-paction="import-progress">导入学习进度 ↑</button></div>`;}
  function renderMaterials(){const counts=Object.entries(C.types).map(([type,title])=>{const qs=bank.questions.filter(q=>q.question_type===type);return {type,title,count:qs.length,graded:qs.filter(q=>q.gradable).length};}).filter(x=>x.count);$('#platform-content').innerHTML=header('每一道题，都能回到出处。','仅在本地读取资料与学习记录。题目、答案、解析、图表的原始来源分别保留。','LIBRARY & DATA')+`<section class="panel"><h2>题库与学习记录</h2><p class="muted" style="margin-top:10px">题库导入支持统一 schema v2。进度导入会合并作答历史、收藏、生词、草稿与作文，保留原阅读进度备份。</p><div class="platform-bank-actions"><button class="button" data-paction="export-bank">导出统一题库 JSON ↓</button><button class="button secondary" data-paction="import-bank">导入题库 JSON ↑</button><button class="button secondary" data-paction="export-progress">导出学习记录 ↓</button><button class="button secondary" data-paction="import-progress">导入学习记录 ↑</button></div><p class="source-note">JSON 中的图片和来源文件使用本地相对路径；新增题图需放入相应 question-images 或 sources 文件夹。未核验题目不参与正式正确率统计。</p></section><h2 class="section-heading">实际导入题型</h2><div class="panel table-scroll"><table class="platform-table"><thead><tr><th>题型</th><th>题数</th><th>可评分</th><th>其余题目</th></tr></thead><tbody>${counts.map(c=>`<tr><td>${E(c.title)}</td><td>${c.count}</td><td>${c.graded}</td><td>${c.count-c.graded}（写作 / 待核验）</td></tr>`).join('')}</tbody></table></div><h2 class="section-heading">原始资料</h2><div class="source-browser">${bank.sources.map(s=>`<article class="panel"><h3>${E(s.title)}</h3><div class="row" style="margin-top:10px"><span class="tag">${s.imported_count||0} 道关联题目</span><span class="tag neutral">${E(s.group||'参考资料')}</span></div><p>${E(s.source_file||s.fileName||'')}</p>${sourceLink(s.id,s.reader?.originalPages?.slice(0,1)||[],'打开本地原资料')}<details class="annotation"><summary>提取与质量说明</summary>${(Array.isArray(s.notes)?s.notes:[s.notes]).filter(Boolean).map(n=>`<p>${E(n)}</p>`).join('')}</details></article>`).join('')}</div><h2 class="section-heading">参考资料与未完整导入内容</h2><div class="stack">${(bank.reference_materials||[]).map(r=>`<details class="panel"><summary>${E(r.title||r.name||r.source_file||r.sourceId||r.source_id||'资料核验说明')}</summary><p>${E(r.reason||r.notes||r.description||r.quality||JSON.stringify(r))}</p>${r.source_id||r.sourceId?sourceLink(r.source_id||r.sourceId,r.source_page||r.pages||[],'查看原页'):''}</details>`).join('')}</div>`;}
  function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
  function essayDocument(e){const q=questions.get(e.questionId);return `${C.types[q?.question_type]||'AWA'}\n${q?.question_content||''}\n\n${q?.instructions||''}\n\n来源：${q?sourceName(q):''} / 原第 ${(q?.source_page||[]).join('、')} 页\n保存：${new Date(e.at).toLocaleString('zh-CN')}\n\n—— 作文 ——\n\n${e.text}\n`;}
  async function importFile(file){
    if(!file)return;
    try{
      if(file.size>250*1024*1024)throw Error('文件超过 250 MB。');
      const input=JSON.parse(await file.text());
      if(importKind==='progress'&&input.version===1&&input.questions){legacy.mergeProgress(input);importLegacy();await save();toast('RC progress imported.');render();return;}
      if(importKind==='bank'){
        const extra=C.validateBank(input),existing=await dbGet('imported-banks')||[];
        if(!db)throw Error('此浏览器无法持久保存导入题库。');
        const oldBank=bank;let count;
        try{count=mergeBank(extra);await dbSet('imported-banks',[...existing,extra]);}catch(e){bank=oldBank;indexBank();throw e;}
        window.GREPortable?.changed();
        toast(`已导入 ${count} 道新题；相同 ID 的已有题目保留。`);
      }else{
        // Validate every part before changing any of the three local stores.
        const next=validState(input.progress||input);
        if(input.legacyRC)legacy.validateProgress(input.legacyRC);
        if(input.mock)await mock.validateImport(input.mock);
        // Rich platform responses must exist before the RC bridge emits history events.
        const attempts=new Map(state.attempts.map(a=>[a.id,a]));
        for(const a of next.attempts){
          const old=attempts.get(a.id);
          attempts.set(a.id,old?{...a,...old,elapsedMs:old.elapsedMs??a.elapsedMs,selected:old.selected?.length?old.selected:a.selected,text:old.text||a.text}:a);
        }
        state.attempts=[...attempts.values()].sort((a,b)=>a.at-b.at);
        state.favorites=[...new Set([...state.favorites,...next.favorites])];
        state.vocabulary=V.mergeEntries(state.vocabulary,next.vocabulary);
        for(const [id,resultAI]of Object.entries(next.questionAnalysis))if(!state.questionAnalysis[id]||resultAI.generatedAt>=state.questionAnalysis[id].generatedAt)state.questionAnalysis[id]=resultAI;
        state.notes={...next.notes,...state.notes};
        state.essays=[...new Map([...state.essays,...next.essays].map(e=>[e.id,e])).values()];
        state.sessions=[...new Map([...state.sessions,...next.sessions].map(s=>[s.id,s])).values()];
        for(const [id,d]of Object.entries(next.drafts))if(!state.drafts[id]||d.updatedAt>state.drafts[id].updatedAt)state.drafts[id]=d;
        if(!state.session)state.session=next.session;
        if(input.legacyRC)legacy.mergeProgress(input.legacyRC);
        if(input.mock)await mock.importProgress(input.mock);
        await save();toast('学习记录已合并，历史作答未覆盖。');
      }
      render();
    }catch(e){toast('导入失败：'+e.message);}finally{$('#platform-import').value='';}
  }
  function showEssay(e){const q=questions.get(e.questionId);$('#platform-content').innerHTML=header('这一版的思考，完整保留。',new Date(e.at).toLocaleString('zh-CN'),'SAVED ESSAY')+`<button class="button secondary small" data-paction="essay-history">← 返回历史作文</button><section class="panel" style="margin-top:20px"><p class="writing-prompt">${E(q?.question_content||'')}</p><hr class="panel-divider"><p class="writing-prompt">${E(e.text)}</p><button class="button secondary" style="margin-top:20px" data-export-essay="${E(e.id)}">导出这一版 ↓</button></section>`;}
  document.addEventListener('click',event=>{
    const b=event.target.closest('button,a');if(!b)return;
    if(b.dataset.vocabWord){saveVocabularyWord(b.closest('.vocabulary-panel'),b.dataset.vocabWord,b.dataset.vocabContext);return;}
    if(b.dataset.vocabRemove){state.vocabulary=V.remove(state.vocabulary,b.dataset.vocabRemove);save();renderVocabularyResults();toast('已移除生词。');return;}
    if(b.dataset.vocabPage){vocabularyPage=Number(b.dataset.vocabPage);renderVocabularyResults();return;}
    if(b.dataset.pview){go(b.dataset.pview);return;}
    if(b.dataset.view){if(view!=='rc'){view='rc';syncVisibility();}return;}
    if(b.matches('.brand')){event.preventDefault();event.stopPropagation();go('home');return;}
    if(b.dataset.popen){const q=questions.get(b.dataset.popen);if(q.category==='AWA')openEssay(q.question_id);else startPractice([q.question_id]);return;}
    if(b.dataset.pfavorite){const id=b.dataset.pfavorite;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();if(view==='essay'){b.textContent=state.favorites.includes(id)?'★':'☆';b.classList.toggle('saved',state.favorites.includes(id));}else render();return;}
    if(b.dataset.legacyPassage){view='rc';syncVisibility();legacy.openPassage(b.dataset.legacyPassage);return;}
    if(b.dataset.ppage){page=Number(b.dataset.ppage);if(view==='errors'||view==='favorites')renderReview();else $('#p-results').innerHTML=pageList(filterQuestions());return;}
    if(b.dataset.pcount){config.count=Number(b.dataset.pcount);renderHome();return;}
    if(b.dataset.poption){const {q,r}=current();if(r.submitted)return;const id=b.dataset.poption,m=C.mode(q);if(m==='blanks'){const group=q.blank_groups.find(g=>g.options.some(o=>o.id===id));r.selected=r.selected.filter(x=>!group.options.some(o=>o.id===x));r.selected.push(id);}else if(m==='pair'||m==='multiple'){if(r.selected.includes(id))r.selected=r.selected.filter(x=>x!==id);else if(m!=='pair'||r.selected.length<2)r.selected.push(id);else{toast('六选二只能选择两个选项，请先取消一个。');return;}}else r.selected=[id];save();document.querySelectorAll('[data-poption]').forEach(el=>{const selected=r.selected.includes(el.dataset.poption);el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',String(selected));});$('[data-paction="submit"]').disabled=!C.complete(q,r);return;}
    if(b.dataset.pnext!==undefined){accrue();state.session.index=Math.max(0,Math.min(state.session.ids.length-1,Number(b.dataset.pnext)));sessionClock=Date.now();save();renderPractice();return;}
    if(b.dataset.exportEssay){const e=state.essays.find(e=>e.id===b.dataset.exportEssay);if(e)download(`GRE-essay-${e.id}.txt`,essayDocument(e),'text/plain;charset=utf-8');return;}
    if(b.dataset.viewEssay){const e=state.essays.find(e=>e.id===b.dataset.viewEssay);if(e)showEssay(e);return;}
    if(b.dataset.sessionResult){const past=state.sessions.find(s=>s.id===b.dataset.sessionResult);if(past?.kind==='mock'){go('mock');mock?.showResult(past.mockExamId);return;}state.session=JSON.parse(JSON.stringify(past));view='practice';render();return;}
    const action=b.dataset.paction;
    if(action==='start')startFiltered();if(action==='resume'){view='practice';sessionClock=Date.now();render();}
    if(action==='submit')submitCurrent();if(action==='finish')finishSession();
    if(action==='essay-history'){accrue();save();view='essay-history';render();}
    if(action==='random-essay'){const list=filterQuestions().filter(q=>q.category==='AWA');const q=shuffled(list.length?list:bank.questions.filter(q=>q.category==='AWA'))[0];if(q)openEssay(q.question_id);}
    if(action==='writing-timer'){writingLimit=Number($('#essay-limit').value);writingEnd=Date.now()+writingLimit*60000;writingExpired=false;tick();}
    if(action==='save-essay'){const d=state.drafts[writingId];if(!d.text.trim()){toast('请先写下作文内容。');return;}accrue();const essay=storeEssay(questions.get(writingId),d.text,d.elapsedMs);state.attempts.push({id:'essay:'+essay.id,questionId:writingId,at:essay.at,correct:null,elapsedMs:d.elapsedMs,selected:[],text:d.text,uncertain:false});save();toast('已保存为新的历史作文版本。');}
    if(action==='export-essay'){const d=state.drafts[writingId];download(`GRE-essay-draft-${writingId}.txt`,essayDocument({questionId:writingId,text:d.text,at:Date.now()}),'text/plain;charset=utf-8');}
    if(action==='export-progress'){accrue();save();download('gre-training-progress.json',JSON.stringify({app:'gre-training-studio',exportedAt:new Date().toISOString(),progress:state,legacyRC:legacy.readProgress(),mock:mock?.exportProgress()},null,2));}
    if(action==='export-bank')download('gre_question_bank.json',JSON.stringify(bank));
    if(action==='import-progress'||action==='import-bank'){importKind=action==='import-bank'?'bank':'progress';$('#platform-import').click();}
  },true);
  document.addEventListener('submit',event=>{if(!event.target.matches('.vocabulary-form'))return;event.preventDefault();const form=event.target,input=form.elements.word;saveVocabularyWord(form.closest('.vocabulary-panel'),input.value);if(V.validWord(input.value))input.value='';});
  document.addEventListener('change',event=>{const el=event.target;if(el.dataset.config){const key=el.dataset.config;config[key]=el.multiple?[...el.selectedOptions].map(o=>o.value):el.type==='checkbox'?el.checked:['count','minutes'].includes(key)?Number(el.value):el.value;if(key==='subject'){config.types=[];config.sources=[];config.group='';}if(key==='mode'&&config.mode==='exam')config.instant=false;page=1;renderHome();}if(el.dataset.ptype){config.types=el.checked?[...new Set([...config.types,el.dataset.ptype])]:config.types.filter(t=>t!==el.dataset.ptype);page=1;$('#filter-count').textContent=`当前符合条件：${filterQuestions().length.toLocaleString()} 题`;$('#p-results').innerHTML=pageList(filterQuestions());}if(el.id==='p-uncertain'){current().r.uncertain=el.checked;save();}if(el.dataset.reviewFilter&&el.type!=='search'){reviewFilter[el.dataset.reviewFilter]=el.value;page=1;renderReview();}if(el.id==='platform-import')importFile(el.files[0]);});
  document.addEventListener('input',event=>{const el=event.target;if(el.id==='vocabulary-search'){vocabularySearch=el.value;vocabularyPage=1;renderVocabularyResults();return;}if(el.id==='p-response-text'){const {q,r}=current();r.text=el.value;save();const submit=$('[data-paction="submit"]');if(submit)submit.disabled=!C.complete(q,r);}if(el.id==='p-note'){const id=current().q.question_id;state.notes[id]=el.value;state.notesUpdatedAt[id]=Date.now();save();}if(el.id==='essay-text'){const d=state.drafts[writingId];d.text=el.value;d.updatedAt=Date.now();save();$('#essay-words').textContent=(el.value.trim()?el.value.trim().split(/\s+/).length:0)+' words';$('#essay-saved').textContent='草稿已自动保存';}if(el.dataset.reviewFilter&&el.type==='search'){const start=el.selectionStart;reviewFilter.search=el.value;page=1;renderReview();const next=$('[data-review-filter="search"]');next.focus();next.setSelectionRange(start,start);}});
  document.addEventListener('error',event=>{if(event.target instanceof HTMLImageElement&&event.target.classList.contains('question-image')){event.target.insertAdjacentHTML('afterend','<p class="image-missing">原题图片未能加载，请通过题目下方的原资料链接核对。</p>');}},true);
  window.addEventListener('beforeunload',()=>{accrue();save();});
  setInterval(tick,1000);setInterval(()=>{if(view==='practice'||view==='essay'){accrue();save();}},15000);
  async function recordMockExam(raw){
    const exam=window.GREMockCore.restore(raw,bank);if(!exam.endedAt)return;
    const sessionId='mock:'+exam.id,existing=new Set(state.attempts.map(a=>a.id));
    const session={id:sessionId,kind:'mock',mockExamId:exam.id,mockVisitedIds:exam.sections.filter(s=>s.endedAt&&s.subject!=='AWA').flatMap(s=>s.ids),ids:exam.sections.flatMap(s=>s.ids),index:0,startedAt:exam.startedAt,endedAt:exam.endedAt,mode:'exam',minutes:118,instant:false,responses:{}};
    for(const section of exam.sections){if(!section.endedAt)continue;for(const id of section.ids){
      const q=questions.get(id),r=exam.responses[id];if(!q||!r)continue;
      const answered=!!(r.text?.trim()||r.selected?.length),at=section.endedAt;
      if(!answered)continue;
      const correct=C.grade(q,r),attemptId=q.legacy_rc_id?`rc:${id}:${at}`:`mock:${exam.id}:${id}`;
      const response={selected:[...(r.selected||[])],text:r.text||'',uncertain:false,elapsedMs:r.elapsedMs||0,submitted:true,correct};
      session.responses[id]=response;
      if(!existing.has(attemptId)){state.attempts.push({id:attemptId,questionId:id,at,correct,elapsedMs:response.elapsedMs,selected:response.selected,text:response.text,uncertain:false,sessionId,origin:'mock'});existing.add(attemptId);if(q.legacy_rc_id)legacy.recordExternal(id,response,correct,at,{preserveTimestamp:initializing||restoring,silent:restoring});}
      if(q.category==='AWA'&&!state.essays.some(e=>e.id===attemptId))state.essays.push({id:attemptId,questionId:id,text:response.text,at,elapsedMs:response.elapsedMs,wordCount:response.text.trim().split(/\s+/).length,origin:'mock'});
    }}
    if(!state.sessions.some(s=>s.id===sessionId))state.sessions.push(session);
    state.attempts.sort((a,b)=>a.at-b.at);await save();
  }
  // Portable snapshots are read-only: collecting one must never change timers,
  // timestamps, or trigger another autosave.
  const cloneProgress=value=>JSON.parse(JSON.stringify(value));
  async function snapshotPortable(){
    const progress=cloneProgress(state),legacyRC=legacy.readProgress(),mockProgress=mock?.exportProgress();
    return {app:'gre-training-studio',progress,legacyRC,mock:mockProgress,importedBanks:await dbGet('imported-banks')||[]};
  }
  function richHistoryRecord(older,newer){
    const result={...older,...newer};
    for(const key of ['selected','ids','mockVisitedIds'])if(!newer[key]?.length&&older[key]?.length)result[key]=older[key];
    if(!newer.text&&older.text)result.text=older.text;
    if(newer.elapsedMs==null&&older.elapsedMs!=null)result.elapsedMs=older.elapsedMs;
    if(older.responses||newer.responses){result.responses={...older.responses};for(const [id,response]of Object.entries(newer.responses||{}))result.responses[id]=older.responses?.[id]?richHistoryRecord(older.responses[id],response):response;}
    return result;
  }
  function unionHistory(older,newer,key=item=>item.id){
    const records=new Map(older.map(item=>[key(item),item]));
    for(const item of newer){const previous=records.get(key(item));records.set(key(item),previous?richHistoryRecord(previous,item):item);}
    return [...records.values()];
  }
  function mergeNotes(older,newer){
    const notes={...older.notes},notesUpdatedAt={...older.notesUpdatedAt};
    for(const [id,note]of Object.entries(newer.notes||{})){
      const nextAt=newer.notesUpdatedAt?.[id]??newer.updatedAt??0,oldAt=older.notesUpdatedAt?.[id]??older.updatedAt??0;
      if(!(id in notes)||nextAt>=oldAt){notes[id]=note;notesUpdatedAt[id]=nextAt;}
    }
    return {notes,notesUpdatedAt};
  }
  function mergePlatformProgress(local,incoming){
    const [older,newer]=incoming.updatedAt>=local.updatedAt?[local,incoming]:[incoming,local];
    const result={...newer,...mergeNotes(older,newer)};
    result.attempts=unionHistory(older.attempts,newer.attempts).sort((a,b)=>a.at-b.at);
    result.essays=unionHistory(older.essays,newer.essays).sort((a,b)=>a.at-b.at);
    result.sessions=unionHistory(older.sessions,newer.sessions).sort((a,b)=>a.endedAt-b.endedAt);
    result.migratedBookmarks=[...new Set([...older.migratedBookmarks,...newer.migratedBookmarks])];
    // Membership comes from the most recently edited collection. Only enrich
    // words still present there, so a deleted word/favorite stays deleted.
    const oldWords=new Map(older.vocabulary.map(entry=>[entry.word,entry]));
    result.vocabulary=newer.vocabulary.map(entry=>V.mergeEntries([entry],oldWords.has(entry.word)?[oldWords.get(entry.word)]:[])[0]);
    result.questionAnalysis={...older.questionAnalysis};for(const [id,resultAI]of Object.entries(newer.questionAnalysis||{}))if(!result.questionAnalysis[id]||resultAI.generatedAt>=result.questionAnalysis[id].generatedAt)result.questionAnalysis[id]=resultAI;
    result.drafts={...older.drafts};for(const [id,draft]of Object.entries(newer.drafts))if(!result.drafts[id]||draft.updatedAt>=result.drafts[id].updatedAt)result.drafts[id]=draft;
    return result;
  }
  function mergeLegacyProgress(local,incoming){
    const [older,newer]=incoming.updatedAt>=local.updatedAt?[local,incoming]:[incoming,local],result={...newer,...mergeNotes(older,newer),questions:{...older.questions}};
    for(const [id,record]of Object.entries(newer.questions)){const previous=result.questions[id];if(!previous||record.lastAt>=previous.lastAt)result.questions[id]=previous?richHistoryRecord(previous,record):record;}
    result.history=unionHistory(older.history,newer.history,item=>`${item.qid}/${item.at}`).sort((a,b)=>a.at-b.at).slice(-30000);
    return result;
  }
  function mergeMockProgress(local,incoming){
    const [older,newer]=incoming.updatedAt>=local.updatedAt?[local,incoming]:[incoming,local];
    const history=unionHistory(older.history,newer.history).sort((a,b)=>b.startedAt-a.startedAt);
    return {...newer,history,active:newer.active&&!history.some(item=>item.id===newer.active.id)?newer.active:null};
  }
  async function restorePortable(input){
    if(!input||input.app!=='gre-training-studio'||!input.progress||!Array.isArray(input.importedBanks??[]))throw Error('这不是有效的阅间完整进度文件，当前记录未改动。');
    const existing=await dbGet('imported-banks')||[],allImported=[...existing],knownBanks=new Set(existing.map(value=>JSON.stringify(value)));
    let candidate=bank;
    for(const raw of input.importedBanks||[]){const extra=C.validateBank(raw),signature=JSON.stringify(extra);candidate=combinedBank(candidate,extra);if(!knownBanks.has(signature)){knownBanks.add(signature);allImported.push(extra);}}
    const candidateIds=new Set(candidate.questions.map(question=>question.question_id));
    const references=[...(input.progress.attempts||[]).map(item=>item?.questionId),...(input.progress.favorites||[]),...Object.keys(input.progress.notes||{}),...Object.keys(input.progress.drafts||{}),...(input.progress.essays||[]).map(item=>item?.questionId),...(input.progress.sessions||[]).flatMap(item=>item?.ids||[]),...(input.progress.session?.ids||[])];
    if(references.some(id=>typeof id!=='string'||!candidateIds.has(id)))throw Error('进度包含尚未提供的题目，请使用包含导入题库的完整进度文件；当前记录未改动。');
    // Validate every component against the combined bank before any write or
    // assignment. A broken file must not replace even one browser store.
    const previousBank=bank;let next;
    try{bank=candidate;indexBank();next=validState(input.progress);}finally{bank=previousBank;indexBank();}
    const nextLegacy=input.legacyRC?legacy.validateProgress(input.legacyRC):legacy.readProgress();
    const nextMock=input.mock?mock.validatePortable(input.mock,candidate):mock.exportProgress();
    const merged=mergePlatformProgress(state,next),mergedLegacy=legacy.validateProgress(mergeLegacyProgress(legacy.readProgress(),nextLegacy)),mergedMock=mock.validatePortable(mergeMockProgress(mock.exportProgress(),nextMock),candidate);
    if(allImported.length&&!db)throw Error('浏览器未提供保存导入题库的空间，当前记录未改动。');
    await saveQueue;
    if(db)await new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite');tx.objectStore('data').put(allImported,'imported-banks');tx.objectStore('data').put(merged,'progress');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||Error('进度写入浏览器失败'));tx.onabort=()=>reject(tx.error||Error('进度写入浏览器中止'));});
    restoring=true;
    try{
      bank=candidate;indexBank();state=merged;storageOK=true;
      legacy.restoreProgress(mergedLegacy);await mock.restorePortable(mergedMock);await save({preserveTimestamp:true,silent:true,force:true});
      sessionClock=Date.now();essayClock=Date.now();writingEnd=null;writingExpired=false;
      if(view==='practice'&&!state.session)view='home';if(view==='essay'&&!state.drafts[writingId])view='writing';
      render();
    }finally{restoring=false;}
  }
  if(mock)await mock.mount($('#mock-content'),{getBank:()=>bank,getSeenIds:()=>state.attempts.map(a=>a.questionId),recordExam:recordMockExam,startSubjectPractice,getPracticeSession,resumeSubjectPractice,toast,go});
  window.GREPlatform={getState:()=>JSON.parse(JSON.stringify(state)),getBank:()=>bank,openQuestion:id=>questions.get(id)?.category==='AWA'?openEssay(id):startPractice([id]),go,snapshotPortable,restorePortable};
  AI?.init({getEntries:()=>state.vocabulary,saveEntry:async(word,raw)=>{const entry=state.vocabulary.find(entry=>entry.word===word),ai=V.normalizeAI(raw,word);if(!entry||!ai)return false;entry.ai=ai;return save();}});
  QA?.init({getResults:()=>state.questionAnalysis,saveResult:async(id,result)=>{state.questionAnalysis[id]=result;return save();}});
  initializing=false;
  const portableReady=window.GREPortable?.init({snapshot:snapshotPortable,restore:restorePortable});
  if(location.hash==='#rc'){view='rc';syncVisibility();legacy.navigate('library');}else{view=location.hash==='#vocabulary'?'vocabulary':location.hash==='#home'?'home':'mock';render();}
  await portableReady;
})();
